export const title = "How to Check Whether a Clamp-On Desk Fan Fits Your Setup";
export const metaTitle = "Will a Clamp-On Desk Fan Fit Your Desk?";
export const metaDescription = "Check a clamp fan’s permitted mounting surface, full head movement, controls, airflow route, and power cable before buying.";
